const body = $input.first().json.body;
if (!body || body.event !== 'process_application.submitted') throw new Error('Invalid event');
if (typeof body.request_id !== 'string' || !/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(body.request_id)) throw new Error('Invalid request_id');
const fields = body.fields;
if (!fields || typeof fields !== 'object' || Array.isArray(fields)) throw new Error('Invalid fields');
const names = ['application_type', 'applicant', 'department', 'permission_level', 'approver', 'additional_info'];
if (Object.keys(fields).some(k => !names.includes(k))) throw new Error('Unknown field');
for (const name of names) {
  if (fields[name] !== null && fields[name] !== undefined && typeof fields[name] !== 'string') throw new Error('Invalid field type');
}
for (const name of ['application_type', 'applicant', 'department']) {
  if (typeof fields[name] !== 'string' || !fields[name].trim()) throw new Error('Missing ' + name);
}
return [{json: {request_id: body.request_id, session_id: body.session_id ?? null, fields}}];
